let metaballShader;
let texture;

const N_balls = 1000;
const metaballs = [];

function hexToRgb(hex) {
  const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
  return [
    parseInt(result[1], 16),
  	parseInt(result[2], 16),
    parseInt(result[3], 16)
  ]
}

function updatePalette() {
	texture = createImage(palette.length, 1);
	texture.loadPixels();
	const colors = palette.map(hexToRgb);
	for (let index = 0; index < colors.length * 4; index++) {
		const channel = index % 4;
		if (channel === 3) {
			texture.pixels[index] = 255;
		}
		texture.pixels[index] = colors[(index - channel) / 4][channel] ?? 255;
	}
	texture.updatePixels();
	metaballShader.setUniform("colors", texture);
	metaballShader.setUniform("colorCount", colors.length);
}

function preload() {
	metaballShader = getShader(this._renderer);
}

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	setAttributes('alpha', true);
	// setAttributes('premultipliedAlpha', true);
	setAttributes('depth', false);
	shader(metaballShader);

	// for (let i = 0; i < N_balls; i ++) metaballs.push(new Metaball());
	updatePalette();
	// noLoop();
}

function parameterChanged(variableName, value) {
    if (variableName === 'palette') {
        updatePalette();
    }
}

function draw() {
	var data = [];
	clear();
	// needed to set transparency correctly
	fill(1,1,1,0);
	const { power: adjustedPower, annotatedMetaballs } = getIntensity();
	for (const ball of annotatedMetaballs) {
		// ball.update();
		data.push(ball.ball.pos.x, ball.ball.pos.y, ball.intensity, ball.radius);
	}
	metaballShader.setUniform("metaballs", data);
	metaballShader.setUniform("smoothing", boolean(smoothing));
	// metaballShader.setUniform("aoe", aoe);
	metaballShader.setUniform("power", adjustedPower);
	metaballShader.setUniform("cutoff", cutoff);
	rect(0, 0, width, height);
}

// OpenProcessing has a bug where it always creates a scrollbar on Chromium.
function mouseWheel() { // This stops the canvas from scrolling by a few pixels.
	return false;
}

function mouseMoved() {
   metaballs.push(new Metaball((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), windowHeight - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 1))
}

function getIntensity() {
  const nearestNeighbours = metaballs.map((p1) => {
    const nearest = metaballs.filter((p2) => {
      const dist = Math.sqrt(
        (p1.pos.x - p2.pos.x) ** 2 + (p1.pos.y - p2.pos.y) ** 2
      );
      return dist <= distance;
    });
    const touching = metaballs.filter((p2) => {
      var dist = Math.sqrt(
        (p1.pos.x - p2.pos.x) ** 2 + (p1.pos.y - p2.pos.y) ** 2
      );
      return dist <= aoe / 2 && dist >= aoe / 4 // approximately
    });
    const close = metaballs.filter((p2) => {
      var dist = Math.sqrt(
        (p1.pos.x - p2.pos.x) ** 2 + (p1.pos.y - p2.pos.y) ** 2
      );
      return dist <= 5;
    });
    return {
      ball: p1,
      neighbours: nearest.length,
      touching: touching.length,
			close: close.length,
    };
  });
  const maxNearestNeighbours = Math.max(
    ...nearestNeighbours.map(({ neighbours }) => neighbours)
  );
  console.log('maxNearestNeighbours', maxNearestNeighbours);
  const power1 = adjustPower ? power / maxNearestNeighbours : power;
  const annotatedMetaballs = nearestNeighbours.map(
    ({ ball: p1, touching, close }) => {
      const intensity = Math.max(1, 2 * touching);
			const radius = aoe * (1 + (close - 1) / metaballs.length);
      return {
        ball: p1,
        intensity: adjustIntensity ? intensity :  1,
				radius: adjustRadius ? radius : aoe,
      };
    }
  );
  return { power: power1, annotatedMetaballs };
}


// === Tab: metaball ===
class Metaball {
	constructor(widthM, heightM, intensity) {
		const size = Math.pow(Math.random(), 2);
		this.vel = p5.Vector.random2D().mult(8 * (1 - size) + 2);
		this.radius = 100 * size + 20;

		this.pos = new p5.Vector(widthM, heightM);
		// this.intensity = Math.random() * (5 - 1) + 1;
		this.intensity = intensity;
	}

	update() {
		this.pos.add(this.vel);

		if (this.pos.x < this.radius || this.pos.x > width  - this.radius) this.vel.x *= -1;
		if (this.pos.y < this.radius || this.pos.y > height - this.radius) this.vel.y *= -1;
	}
}

// === Tab: shader ===
function getShader(_renderer) {
	const vert = `
		attribute vec3 aPosition;
		attribute vec2 aTexCoord;

		varying vec2 vTexCoord;

		void main() {
			vTexCoord = aTexCoord;

			vec4 positionVec4 = vec4(aPosition, 1.0);
			positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

			gl_Position = positionVec4;
		}
	`;

	const frag = `
		precision highp float;

		varying vec2 vTexCoord;

		uniform vec4 metaballs[${N_balls}];
		uniform sampler2D colors;
		uniform float cutoff;
		uniform float power;
		uniform float colorCount;
		uniform bool smoothing;

		const float WIDTH = ${windowWidth}.0;
		const float HEIGHT = ${windowHeight}.0;

		const float FADEOUT = 3.0;

		const float UPPERBOUND = 1.1;

		vec3 hsv2rgb(vec3 c) {
				vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
				vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
				return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
		}

		float distsq(vec2 a, vec2 b, float aoe) {
			return pow(max(0.0, 0.5 - distance(a, b) / aoe), 2.0);
		}

		void main() {
			float x = vTexCoord.x * WIDTH;
			float y = vTexCoord.y * HEIGHT;
			float sum = 0.0;

			for (int i = 0; i < ${N_balls}; i++) {
				vec4 ball = metaballs[i];
				float intensity = ball.z;
				float diff = 0.5 * distsq(vec2(x, y), ball.xy, ball.w) * intensity;
				sum += diff * power;
			}

			// TODO: how to remove the if here
			if (cutoff < sum) {
				float value = clamp(sum - cutoff, 0.0, 1.0);
				float colorIndex = colorCount * value;
				float startColorIndex = floor(colorIndex);
				float endColorIndex = ceil(colorIndex);
				vec4 startColor = texture2D(colors, vec2((startColorIndex + 0.5) / colorCount, 0.5));
				vec4 color = startColor;
				// TODO: remove this if in actual implementation and hardcode the one you want
				if (smoothing) {
				 	vec4 endColor = texture2D(colors, vec2((endColorIndex + 0.5) / colorCount, 0.5));
					// perform smoother transition between colors
					float mantissa = colorIndex - floor(colorIndex);
				 	color = mix(startColor, endColor, mantissa);
					// TODO: how to remove the if here
					if (startColorIndex == 0.0) {
						color.a = color.a * (smoothstep(0.0, 1.0, mantissa * FADEOUT));
					}
			  } 
				gl_FragColor = color;
			}
		}
	`;

	return createShader(vert, frag);
}

